#!/usr/bin/env python3
"""Native geometry-only evidence and scope record for the boundary rebuild."""
from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1]
r=root/'docs/reports/canyon-contour-rebuild'
def read(name):
 p=r/name
 return p.read_text() if p.exists() else ''
def fields(name,tag):
 m=re.search(tag+r' (.*)',read(name))
 return dict(re.findall(r'(\w+)=([^\s]+)',m.group(1))) if m else {}
checks={name:('PASS' if ('PASS' in read(name+'.log') or '100% tests passed' in read(name+'.log')) and 'FAIL' not in read(name+'.log') else 'pending / failed') for name in ['geometry-tests','graphics-tests','occlusion-tests','gameplay-tests']}
g=fields('geometry-tests.log','GEOMETRY')
bench={name:fields(file,'BENCHMARK') for name,file in [('historical_before','benchmark-before-historical.log'),('current','benchmark-current.log')]}
render={name:fields(file,'CANYON_RENDER:') for name,file in [('historical_before','benchmark-before-historical.log'),('current','benchmark-current.log')]}
remaining=[
 'The low collision skirt still follows the immutable floor boundary; parts of that outline remain visible. Main cliff contours are independent, but this is not a claim that every visual trace of the old room outline has disappeared.',
 'Some faces remain more planar and angular than the target. The report does not certify exact visual equivalence.',
 'Detached room boulders were deliberately retained, so their regular lower footprints are outside this boundary-only correction.',
 'No decoration rules were changed. Existing terrain-aware support tests naturally resample candidate acceptance and root height against the new terrain; generated placements can therefore differ.',
 'The visual rock profile remains separate from canonical collision/projectile volumes. Those physical volumes are unchanged.',
 'Only native Linux was built and exercised. WASM checks remain waived.'
]
measure={'scope':'Boundary geometry only, relative to the uncommitted canyon-composition pass at task start. Earlier uncommitted material/dressing changes are not part of this task.','checks':checks,'geometry':g,'benchmark':bench,'render':render,'camera':{'zoom':160,'fov':45,'resolution':[1440,900],'seed':1866,'scene':'profile-works','geometry_diagnostic_player_marker_height':1.8},'remaining':remaining,'status':'Rejected by user; reverted to preceding canyon-composition snapshot','active_geometry':'preceding canyon-composition pass','visual_acceptance':'FAILED','performance_scope':'Historical before stress capture from the preceding pass versus a fresh current capture, same stress seed/workload. Not an isolated paired experiment or a statistical speedup claim.'}
(r/'measurements.json').write_text(json.dumps(measure,indent=2)+'\n')
css='''*{box-sizing:border-box}body{margin:0;background:#171c20;color:#eee2cc;font:17px/1.6 system-ui,sans-serif}main{max-width:1600px;margin:auto;padding:38px 24px}h1{font-size:clamp(30px,4vw,56px);line-height:1.1}h2{color:#e4b47c;margin-top:42px}a{color:#86d1bf}p,li{max-width:1100px}img{display:block;width:100%;height:auto}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}figcaption{color:#b7ac9b;padding:10px 0;font-size:14px}.note{border-left:4px solid #c18b53;background:#2d2923;padding:18px}code,pre{background:#253034;border-radius:5px}code{padding:2px 5px}pre{padding:18px;overflow:auto}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid #3c484f;text-align:left}.scroll{overflow:auto}summary{cursor:pointer;color:#86d1bf}@media(max-width:700px){.pair{grid-template-columns:1fr}main{padding:20px 14px}}'''
h='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard · Canyon boundary contour rebuild</title><style>'''+css+'''</style><main><p class="note"><b>REJECTED AND REVERTED.</b> The user judged this geometry significantly worse. The active game has been restored to the preceding canyon-composition pass. Captures and rejected source remain here only as historical evidence; diagnostic build commands below are archived and no longer registered. The low rim, broad flat tops and large masses failed the visual target. Reference fidelity remains unfinished.</p><p>DeathWard · Boundary geometry only · November 2026</p><h1>Rock masses replace<br>the cell-extruded rim.</h1><p class="note">This is a geometry replacement, not another material or decoration pass. The principal cliff contours now form separate protrusions, recesses and local terraces. <b>The low skirt still marks the fixed physical boundary.</b> The images below expose that remaining limitation; native test passes do not certify an exact visual match.</p><h2>Geometry-only render</h2><p>A standalone diagnostic draws the actual generated triangles with neutral normal shading and a 1.8-metre scale marker. No vegetation, props, textures, UI, shadows or post-processing are drawn. This diagnostic shader is not used by the game. Camera is the production 160% zoom / 45° perspective setting and Works room position.</p><a href="geometry-only.png"><img src="geometry-only.png" alt="Actual neutral geometry-only rendering"></a><p><a href="geometry-capture.log">Diagnostic capture log</a></p><h2>Authoritative target and current native game</h2><p>The supplied target's room seed and exact camera pose are unknown. The native before/after uses the same seed, scene, frame count and unchanged camera. Images are unretouched game renders; no image-generation or paint-over is used.</p>'''
for name,title in [('works','Open combat room'),('power','A second room with localized formations')]:
 h+=f'<h3>{title}</h3><div class="pair"><figure><a href="target.png"><img src="target.png" alt="Supplied target specification"></a><figcaption>Supplied target.</figcaption></figure><figure><a href="final-{name}.png"><img src="final-{name}.png" alt="Current native canyon"></a><figcaption>Current native capture · <a href="final-{name}.log">Log</a></figcaption></figure></div>'
h+='''<h2>Matched native before / after</h2><div class="pair"><figure><a href="before-works.png"><img src="before-works.png" alt="Previous boundary geometry"></a><figcaption>Before this task · prior uncommitted pass.</figcaption></figure><figure><a href="final-works.png"><img src="final-works.png" alt="Rebuilt boundaries"></a><figcaption>After · same scene and camera.</figcaption></figure></div>
<h2>Exact causes and smallest architectural replacement</h2><p><code>buildCanyon()</code> in <code>CanyonTerrain.cpp</code> constructs the canonical solid height field from room basins, reserved passage paths and detached obstacles. It is unchanged. In <code>buildCanyonAppearance()</code>, the former <code>clip</code>, <code>wall</code> and <code>cap</code> lambdas extruded each source triangle separately. The first face inherited the floor boundary; higher masks were clipped on the same 1.25-metre lattice. Thus coherent noise still produced a cell-sized column pattern and terrace ribbons.</p><p>The replacement is <code>rebuildCanyonCliffs()</code> in <code>CanyonCliffs.cpp</code>. It retains the existing floor and detached boulders, replacing only boundary rock. The existing renderer and spatial bins are reused.</p><ol><li><b>Extract complete rings:</b> <code>contours()</code> clips the solid mask and cancels internal triangle edges. Shared boundary edges become closed polygon rings.</li><li><b>Create independent masses:</b> irregularly spaced sites along the required boundary seat asymmetric, lobed rock masses in the existing non-playable space. They union with a recessed background plateau. Coherent variation operates at roughly 8- and 21-metre scales. The resulting principal contour no longer directly traces the room edge.</li><li><b>Simplify real contours:</b> <code>simplify()</code> removes source-lattice subdivisions while retaining coherent bends. Faces use resulting contour corners, not uniform point spacing.</li><li><b>Make local terraces:</b> independently gated elliptical/lobed geological patches intersect the rock region. They create isolated short upper formations rather than a second offset around every room.</li><li><b>Construct caps and steep faces:</b> polygon differences define exposed top surfaces; Earcut triangulates outer rings and holes. Cap subdivision preserves planar surfaces. Shared corner normals and staggered, signed mid-face relief form broad facets without cracks between faces or one consistent mid-height ridge.</li><li><b>Preserve the physical footprint:</b> a roughly 0.6–0.8-metre skirt meets the original boundary. All new mass footprints remain within its solid mask; a small inset keeps facet relief clear of the playable floor. Canonical terrain, collision, sockets and room graph are untouched.</li><li><b>Reuse rendering/picking:</b> triangles are assigned stable owner cells for rendering and indexed by their real bounds for visual height, ray and occlusion queries.</li></ol>
<p>Clipper2 performs robust polygon unions/differences/intersections; Earcut handles caps with holes. Both are vendored and licensed under <code>third_party/canyon/</code>, so no system Boost or network dependency is added to normal builds. Source URLs and snapshot hashes are preserved in <code>SOURCES.txt</code>.</p>
<h2>Visual corrections during this task</h2><p>The first replacement left an excessively wide low shelf. A second version reduced the setback but still looked like one continuous scenic wall. The final version seats separate chunky masses along the boundary and keeps the continuous plateau farther back. Formation height was then increased relative to the player marker. Consistent outward mid-face relief was replaced with signed relief because it shaded as another horizontal stripe.</p><p>Main formations are approximately four metres high under the current configuration, with taller local patches and a 6.8-metre cap. The actual twelve-map median and maximum are recorded below. Their steep faces and horizontal tops remain distinct; the new geometry does not form broad diagonal ramps.</p><h2>Validation</h2><div class="scroll"><table><tr><th>Suite</th><th>Status</th><th>Evidence</th></tr>'''
for name,status in checks.items():h+=f'<tr><td>{name}</td><td>{status}</td><td><a href="{name}.log">Log</a></td></tr>'
h+='''</table></div><p>CPU checks cover twelve maps, all river categories, deterministic output, original terrain/navigation hashes, 180 sampled room collision/trace checks, cap/face area, supported roots, road clearance, budgets and rollback. GPU tests cover five seeds in both themes, native mesh/ray agreement, density stability and texture/material preservation. Occlusion tests exercise native transparency, enemy outlines and actual mouse firing at ordinary and rotated views. Four unchanged gameplay suites cover roads, rivers, generated floors and room graphs.</p><p>The density test now permits equal 100%/200% counts only when the configured hard instance budget was already full at 100%. Below the cap it still requires an increase; fixed props, monotonic subsets and exact restoration are still checked. No placement rule or budget was changed.</p><pre>'''+json.dumps(g,indent=2)+'''</pre><h2>Performance observation</h2><p>Historical prior-pass stress log versus a fresh current 240-frame stress run. Same seed and workload; these are not ordinary gameplay frame rates or an isolated benchmark of geometry alone. Terrain-aware dressing may accept different candidates on the new mesh, so scenery counts can differ despite unchanged rules.</p><div class="scroll"><table><tr><th>Metric</th><th>Historical before</th><th>Current</th></tr>'''
for key in ['mean_ms','p95_ms','draw_ms','present_ms']:
 h+=f'<tr><td>{key}</td><td>{bench["historical_before"].get(key,"pending")}</td><td>{bench["current"].get(key,"pending")}</td></tr>'
h+='</table></div>'
for name,data in render.items():
 if data:h+=f'<p>{name}: {data.get("triangles","?")} terrain triangles, {data.get("chunks","?")} chunks, {data.get("instances","?")} scenery instances.</p>'
h+='''<p><a href="benchmark-before-historical.log">Historical stress log</a> · <a href="benchmark-current.log">Current stress log</a> · <a href="measurements.json">Measurements</a> · <a href="native-build.log">Build</a></p><h2>Scope, reproducibility and remaining differences</h2><p>This task adds <code>CanyonCliffs.*</code>, its portable polygon dependencies and a standalone geometry diagnostic; it integrates the mesh in <code>CanyonAppearance.cpp</code> and adds CMake/test/report support. It does not edit combat, room graph, controls, camera, UI, lighting, materials, vegetation assets/densities or prop-placement rules. Earlier uncommitted changes from the preceding task remain separate.</p><pre>cmake --build build --target deathward deathward_canyon_geometry_capture -j4
./build/deathward_canyon_geometry_capture docs/reports/canyon-contour-rebuild/geometry-only.png
./build/deathward --expedition --theme canyon --style original

# Existing original-terrain rollback remains available
DEATHWARD_CANYON_CONFIG=assets/visual/canyon-legacy.cfg ./build/deathward</pre><ul>'''
for gap in remaining:h+='<li>'+gap+'</li>'
h+='''</ul><p>The main architecture is no longer the blocker it was in the previous pass. Further boundary-only work should refine individual mass contours/facets against the reference, rather than add room-wide terrace bands. Completely hiding the low collision skirt while preserving its exact footprint remains a visual/readability trade-off, not something certified by the test suite.</p><details><summary>Retained intermediate geometry</summary><p>Discarded versions make the structural changes inspectable.</p>'''
for name in ['geometry-only-pass2','geometry-only-pass3','pass1-works','pass2-works','pass3-works']:
 h+=f'<figure><a href="{name}.png"><img loading="lazy" src="{name}.png" alt="Intermediate {name}"></a><figcaption>{name} · intermediate, not final.</figcaption></figure>'
h+='''</details></main></html>'''
(r/'index.html').write_text(h)
print(json.dumps(checks,indent=2))
